let preferredLanguage;
try { preferredLanguage = localStorage.getItem('portfolio-language'); } catch {}
const requestedLanguage = new URLSearchParams(location.search).get('lang');
window.portfolioLanguage = ['pt','en'].includes(requestedLanguage) ? requestedLanguage : preferredLanguage === 'en' ? 'en' : 'pt';
try { localStorage.setItem('portfolio-language', window.portfolioLanguage); } catch {}
window.portfolioTranslate = value => window.portfolioLanguage === 'en' ? english[value] || value : value;
window.translatePortfolio = root => {
 if (window.portfolioLanguage !== 'en') return;
 const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode:node=>['SCRIPT','STYLE'].includes(node.parentElement?.tagName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
 for (let node; (node=walker.nextNode());) {
  const key=node.textContent.trim();
  if (english[key]) node.textContent=node.textContent.replace(key,english[key]);
 }
 root.querySelectorAll('[aria-label],[aria-roledescription],[alt],meta[content]').forEach(element=>{
  for (const attribute of ['aria-label','aria-roledescription','alt','content']) {
   const value=element.getAttribute(attribute);
   if(english[value]) element.setAttribute(attribute,english[value]);
  }
 });
 if(root.nodeType===Node.ELEMENT_NODE){
  for(const attribute of ['aria-label','aria-roledescription']){
   const value=root.getAttribute(attribute);
   if(english[value])root.setAttribute(attribute,english[value]);
  }
 }
};
document.documentElement.lang=window.portfolioLanguage==='en'?'en':'pt-BR';
document.querySelectorAll('[data-lang]').forEach(link=>{
 link.setAttribute('aria-current',String(link.dataset.lang===window.portfolioLanguage));
 const destination=new URL(location.href);destination.searchParams.set('lang',link.dataset.lang);link.href=destination.href;
});
